use serde::{Deserialize,Serialize};
#[derive(Debug,Clone,Copy,PartialEq,Eq,Serialize,Deserialize,Default)]#[serde(rename_all="snake_case")]pub enum LineEnding{#[default]Lf,CrLf,Cr}
impl LineEnding{pub fn label(self)->&'static str{match self{Self::Lf=>"LF",Self::CrLf=>"CRLF",Self::Cr=>"CR"}}pub fn sequence(self)->&'static str{match self{Self::Lf=>"\n",Self::CrLf=>"\r\n",Self::Cr=>"\r"}}pub fn detect(bytes:&[u8])->Self{let(mut lf,mut crlf,mut cr)=(0,0,0);let mut i=0;while i<bytes.len(){match bytes[i]{b'\r'=>if bytes.get(i+1)==Some(&b'\n'){crlf+=1;i+=2}else{cr+=1;i+=1},b'\n'=>{lf+=1;i+=1},_=>i+=1}}if crlf>=lf&&crlf>=cr&&crlf>0{Self::CrLf}else if lf>=cr&&lf>0{Self::Lf}else if cr>0{Self::Cr}else{Self::Lf}}pub fn normalize_to_lf(text:&str)->String{let mut out=String::with_capacity(text.len());let mut chars=text.chars().peekable();while let Some(c)=chars.next(){if c=='\r'{if chars.peek()==Some(&'\n'){chars.next();}out.push('\n')}else{out.push(c)}}out}pub fn apply(self,text:&str)->String{let text=Self::normalize_to_lf(text);if self==Self::Lf{text}else{text.replace('\n',self.sequence())}}}
